WITH scored AS (SELECT id, store_id, SUM(quantity) OVER (PARTITION BY product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_quantity, SUM(quantity) OVER (PARTITION BY product_id, store_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_quantity_2, AVG(quantity) OVER (PARTITION BY product_id, store_id ORDER BY last_restock, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS quantity_avg_6_prior FROM inventory) SELECT store_id, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS cnt, COUNT(*) AS num_rows, AVG(quantity_avg_6_prior) AS avg_quantity_avg_6_prior FROM scored GROUP BY store_id HAVING distinct_ids < 1000 ORDER BY cnt DESC
